//B"H

const MAX_STEPS = 40;

/**
 * Evaluates a tiny visual automation graph into one next action.
 *
 * Supported nodes:
 * - condition: if lastReply contains `match`, choose onTrue/onFalse.
 * - send: produce a prompt.
 * - archive: tag the last reply, then continue to next.
 * - stop: stop automation.
 */
export function evaluateAutomationGraph(graph = {}, context = {}) {
  const nodes = new Map((graph.nodes || []).map(node => [node.id, node]));
  let node = nodes.get(graph.start) || graph.nodes?.[0];
  const visited = new Set();
  for (let step = 0; step < MAX_STEPS && node; step++) {
    if (visited.has(node.id)) return { stop: true, reason: `graph loop detected at ${node.id}`, nodeId: node.id };
    visited.add(node.id);
    if (node.type === "stop") return { stop: true, reason: node.label || "graph stopped", nodeId: node.id };
    if (node.type === "archive") {
      const next = nodes.get(node.next);
      if (!next) return { stop: true, reason: `archive node ${node.id} has no next`, nodeId: node.id, archiveTag: node.archiveTag || node.id };
      node = next;
      continue;
    }
    if (node.type === "condition") {
      const matched = conditionMatches(node, context);
      node = nodes.get(matched ? node.onTrue : node.onFalse);
      continue;
    }
    if (node.type === "send") {
      return {
        stop: false,
        prompt: template(node.prompt || context.settings?.prompt || "continue", context),
        archiveTag: node.archiveTag || "",
        nodeId: node.id
      };
    }
    return { stop: true, reason: `unknown node type ${node.type}`, nodeId: node.id };
  }
  return { stop: true, reason: "graph ended without send node" };
}

function conditionMatches(node = {}, context = {}) {
  const needle = String(node.match || "");
  const haystack = String(context.lastReply || "");
  let base = true;
  if (needle && node.regex) {
    try { base = new RegExp(needle, node.flags || "i").test(haystack); }
    catch { base = false; }
  } else if (needle) {
    base = haystack.toLowerCase().includes(needle.toLowerCase());
  }
  return node.negate ? !base : base;
}

function template(text = "", context = {}) {
  const values = {
    "settings.prompt": context.settings?.prompt || "continue",
    "lastReply": context.lastReply || "",
    "conversationId": context.conversationId || "",
    "turn": String(context.turn || "")
  };
  return String(text).replace(/{{\s*([^}]+?)\s*}}/g, (_, key) => values[key] ?? "");
}
